//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is safe to retry.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < config.max_attempts => {
                sleeper.sleep_ms(retry_delay(config, attempts));
            }
            Err(error) => return Err(error),
        }
    }
}

fn retry_delay(config: &RetryConfig, retry_number: u32) -> u64 {
    // Checked arithmetic prevents large attempt counts from wrapping.
    let multiplier = if retry_number.saturating_sub(1) >= 64 {
        u64::MAX
    } else {
        1u64 << (retry_number - 1)
    };
    config
        .base_delay_ms
        .checked_mul(multiplier)
        .unwrap_or(u64::MAX)
        .min(config.max_delay_ms)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig { max_attempts, base_delay_ms, max_delay_ms }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let calls = Cell::new(0);
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls.set(calls.get() + 1);
            if calls.get() == 4 { Ok(()) } else { Err(RetryError::Transient("temporary".into())) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls.get(), 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let calls = Cell::new(0);
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_first_call_and_large_exponents_saturate() {
        let mut sleeper = FakeSleeper::default();
        let calls = Cell::new(0);
        let result = run_job(&config(70, u64::MAX, 123), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Transient("still down".into()))
        });

        assert!(result.is_err());
        assert_eq!(calls.get(), 70);
        assert_eq!(sleeper.sleeps.len(), 69);
        assert!(sleeper.sleeps.iter().all(|&delay| delay == 123));
    }
}

