mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(retry_delay(config, attempt));
            }
        }
    }
}

fn retry_delay(config: &RetryConfig, retry_number: u32) -> u64 {
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);
    let mut remaining_doublings = retry_number.saturating_sub(1);

    while remaining_doublings > 0 && delay < config.max_delay_ms {
        delay = delay.saturating_mul(2).min(config.max_delay_ms);
        remaining_doublings -= 1;
    }

    delay
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_growth_is_bounded() {
        let config = RetryConfig { max_attempts: 5, base_delay_ms: 3, max_delay_ms: 10 };
        assert_eq!(retry_delay(&config, 1), 3);
        assert_eq!(retry_delay(&config, 2), 6);
        assert_eq!(retry_delay(&config, 3), 10);
        assert_eq!(retry_delay(&config, 4), 10);
    }

    #[test]
    fn delay_calculation_does_not_overflow() {
        let config = RetryConfig { max_attempts: u32::MAX, base_delay_ms: u64::MAX, max_delay_ms: u64::MAX };
        assert_eq!(retry_delay(&config, u32::MAX), u64::MAX);
    }
}

