#[test]
fn public_policy_saturates_for_large_attempt_numbers() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: 1,
        max_delay_ms: 100,
    };

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 66 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 66);
    assert_eq!(sleeper.sleeps.len(), 65);
    assert!(sleeper.sleeps[63..].iter().all(|&delay| delay == 100));
}

